def _narad_api_route_audit(
    sender,
    receiver,
    max_hops=None
):

    (
        sender,
        receiver
    ) = (

        _narad_api_canonical_endpoints(

            sender,

            receiver
        )
    )


    (
        valid_paths,
        rejected_paths,
        physical_paths
    ) = (

        phase4_discover_valid_quantum_paths(

            network=(
                phase4_network
            ),

            sender_name=(
                sender
            ),

            receiver_name=(
                receiver
            ),

            max_hops=(
                max_hops
            )
        )
    )


    quality_config = (
        _narad_current_quality_config()
    )


    qber_limit = float(

        quality_config
        .qber_limit
    )


    tolerance = float(

        quality_config
        .numerical_tolerance
    )


    # ------------------------------------------------------------------
    # Physical paths rejected because another USER occurs internally.
    # ------------------------------------------------------------------

    role_rejections = []


    for rejected in rejected_paths:

        role_rejections.append({

            "nodes":
                list(
                    rejected.node_names
                ),

            "path":
                " -> ".join(
                    rejected.node_names
                ),

            "reason":
                rejected.reason,

            "offending_user":
                rejected.offending_user
        })


    candidate_audit = []

    executable_records = []


    # ------------------------------------------------------------------
    # Every role-valid candidate.
    # ------------------------------------------------------------------

    for candidate in valid_paths:

        metrics = (

            phase4_evaluate_candidate_path(

                network=(
                    phase4_network
                ),

                candidate_path=(
                    candidate
                )
            )
        )


        rejection_reasons = []


        # ==============================================================
        # HARDWARE / CONTROL RESOURCE FEASIBILITY
        # ==============================================================

        if not bool(
            metrics.all_nodes_active
        ):

            rejection_reasons.append(
                "INACTIVE_NODE"
            )


        if not bool(
            metrics.all_links_active
        ):

            rejection_reasons.append(
                "INACTIVE_LINK"
            )


        if not bool(
            metrics.multiplexing_feasible
        ):

            rejection_reasons.append(
                "INSUFFICIENT_MULTIPLEXING"
            )


        if not bool(
            metrics.memory_feasible
        ):

            rejection_reasons.append(
                "INSUFFICIENT_MEMORY"
            )


        if not bool(
            metrics.bsm_feasible
        ):

            rejection_reasons.append(
                "INSUFFICIENT_BSM_RESOURCES"
            )


        resource_feasible = (

            len(
                rejection_reasons
            )
            ==
            0
        )


        # ==============================================================
        # REQUEST-SCOPED FRESH QUALITY GATE
        # ==============================================================

        fresh_qkd_feasible = bool(

            float(
                metrics.predicted_qber
            )

            <=

            (
                qber_limit
                +
                tolerance
            )
        )


        if (

            resource_feasible

            and

            not fresh_qkd_feasible
        ):

            rejection_reasons.append(
                "FRESH_QBER_EXCEEDS_REQUEST_LIMIT"
            )


        policy_c = None


        # ==============================================================
        # EMPIRICAL POLICY-C QUALITY
        # ==============================================================

        if (

            resource_feasible

            and

            fresh_qkd_feasible
        ):

            policy_c = (

                _narad_policy_c_evaluate_candidate(

                    network=(
                        phase4_network
                    ),

                    candidate_path=(
                        candidate
                    ),

                    raw_metrics=(
                        metrics
                    )
                )
            )


            if not policy_c[
                "empirical_qkd_feasible"
            ]:

                rejection_reasons.append(
                    "DELIVERED_QBER_EXCEEDS_REQUEST_LIMIT"
                )


        executable = bool(

            resource_feasible

            and

            fresh_qkd_feasible

            and

            policy_c is not None

            and

            policy_c[
                "empirical_qkd_feasible"
            ]
        )


        if executable:

            executable_records.append(
                policy_c
            )


        audit_row = {

            "path_index":
                int(
                    candidate.path_index
                ),

            "path":
                candidate.display_path,

            "nodes":
                list(
                    candidate.node_names
                ),

            "repeaters":
                list(
                    candidate.repeater_names
                ),

            "hop_count":
                int(
                    candidate.hop_count
                ),

            "repeater_count":
                int(
                    candidate.repeater_count
                ),

            "total_distance_km":
                float(
                    metrics.total_distance_km
                ),

            "fresh_predicted_visibility":
                float(
                    metrics.predicted_werner_visibility
                ),

            "fresh_predicted_qber":
                float(
                    metrics.predicted_qber
                ),

            "requested_qber_limit":
                qber_limit,

            "resource_feasible":
                resource_feasible,

            "fresh_qkd_feasible":
                fresh_qkd_feasible,

            "executable":
                executable,

            "rejection_reasons":
                list(
                    rejection_reasons
                )
        }


        if policy_c is not None:

            audit_row.update({

                "policy_c_score":
                    float(
                        policy_c[
                            "score"
                        ]
                    ),

                "predicted_service_probability":
                    float(
                        policy_c[
                            "predicted_service_probability"
                        ]
                    ),

                "predicted_median_delivery_s":
                    float(
                        policy_c[
                            "predicted_median_delivery_s"
                        ]
                    ),

                "predicted_delivered_visibility":
                    float(
                        policy_c[
                            "predicted_delivered_visibility"
                        ]
                    ),

                "predicted_delivered_qber":
                    float(
                        policy_c[
                            "predicted_delivered_qber"
                        ]
                    ),

                "within_calibration_domain":
                    bool(
                        policy_c[
                            "within_calibration_domain"
                        ]
                    ),

                "extrapolation_fields":
                    list(
                        policy_c[
                            "extrapolation_fields"
                        ]
                    )
            })


        else:

            audit_row.update({

                "policy_c_score":
                    None,

                "predicted_service_probability":
                    None,

                "predicted_median_delivery_s":
                    None,

                "predicted_delivered_visibility":
                    None,

                "predicted_delivered_qber":
                    None,

                "within_calibration_domain":
                    None,

                "extrapolation_fields":
                    []
            })


        candidate_audit.append(
            audit_row
        )


    # ==================================================================
    # Rank executable candidates exactly as Policy C does.
    # ==================================================================

    executable_records.sort(

        key=lambda record: (

            -record[
                "score"
            ],

            -record[
                "predicted_service_probability"
            ],

            record[
                "predicted_median_delivery_s"
            ],

            -record[
                "predicted_delivered_visibility"
            ],

            record[
                "candidate"
            ]
            .path_index
        )
    )


    rank_by_path_index = {

        record[
            "candidate"
        ].path_index:
            rank

        for rank, record
        in enumerate(
            executable_records,
            start=1
        )
    }


    audit_by_index = {

        row[
            "path_index"
        ]:
            row

        for row
        in candidate_audit
    }


    ranked_routes = []


    for rank, record in enumerate(

        executable_records,

        start=1
    ):

        candidate = (
            record[
                "candidate"
            ]
        )


        ranked_routes.append({

            "rank":
                rank,

            "path_index":
                candidate.path_index,

            "path":
                candidate.display_path,

            "nodes":
                list(
                    candidate.node_names
                ),

            "repeaters":
                list(
                    candidate.repeater_names
                ),

            "score":
                float(
                    record[
                        "score"
                    ]
                ),

            "service_probability":
                float(
                    record[
                        "predicted_service_probability"
                    ]
                ),

            "predicted_delivery_s":
                float(
                    record[
                        "predicted_median_delivery_s"
                    ]
                ),

            "predicted_visibility":
                float(
                    record[
                        "predicted_delivered_visibility"
                    ]
                ),

            "predicted_qber":
                float(
                    record[
                        "predicted_delivered_qber"
                    ]
                ),

            "requested_qber_limit":
                float(
                    record[
                        "requested_qber_limit"
                    ]
                ),

            "bottleneck_elementary_distance_km":
                float(
                    record[
                        "bottleneck_elementary_distance_km"
                    ]
                ),

            "bottleneck_mux_success":
                float(
                    record[
                        "bottleneck_multiplexed_success_probability"
                    ]
                ),

            "within_calibration_domain":
                bool(
                    record[
                        "within_calibration_domain"
                    ]
                ),

            "extrapolation_fields":
                list(
                    record[
                        "extrapolation_fields"
                    ]
                )
        })


    for row in candidate_audit:

        row[
            "rank"
        ] = (

            rank_by_path_index.get(

                row[
                    "path_index"
                ]
            )
        )


    return {

        "sender":
            sender,

        "receiver":
            receiver,

        "requested_qber_limit":
            qber_limit,

        "physical_paths":
            len(
                physical_paths
            ),

        "role_valid_paths":
            len(
                valid_paths
            ),

        "rejected_user_transit_paths":
            len(
                rejected_paths
            ),

        "executable_route_count":
            len(
                executable_records
            ),

        "status":
            (
                "EXECUTABLE_ROUTES_AVAILABLE"

                if executable_records

                else

                "NO_EXECUTABLE_ROUTE"
            ),

        "ranked_routes":
            ranked_routes,

        "role_rejections":
            role_rejections,

        "candidate_audit":
            candidate_audit
    }

