@app.post("/message/send")
def send_message(
    request: MessageSendRequest
):

    session = (

        narad_api_get_session(
            request.session_id
        )
    )


    try:

        (
            sender,
            receiver
        ) = (

            _narad_api_canonical_endpoints(

                request.sender,

                request.receiver
            )
        )


    except Exception:

        raise HTTPException(

            status_code=403,

            detail=(
                "Message endpoints do not match "
                "the authenticated NARAD-QC session."
            )
        )


    if (

        sender
        !=
        session[
            "sender"
        ]

        or

        receiver
        !=
        session[
            "receiver"
        ]
    ):

        raise HTTPException(

            status_code=403,

            detail=(
                "Message endpoints do not match "
                "the authenticated NARAD-QC session."
            )
        )


    plaintext = (

        request.message
        .encode(
            "utf-8"
        )
    )


    encrypted_blob = (

        aes_gcm_encrypt(

            plaintext,

            session[
                "key"
            ]
        )
    )


    ciphertext_b64 = (

        base64.b64encode(
            encrypted_blob
        )
        .decode(
            "ascii"
        )
    )


    with NARAD_API_SESSION_LOCK:

        session[
            "message_count"
        ] += 1


        message_index = (
            session[
                "message_count"
            ]
        )


    return {

        "session_id":
            request.session_id,

        "message_index":
            message_index,

        "sender":
            sender,

        "receiver":
            receiver,

        "cipher":
            "AES-GCM",

        "ciphertext_b64":
            ciphertext_b64,

        "plaintext_bytes":
            len(
                plaintext
            ),

        "encrypted_blob_bytes":
            len(
                encrypted_blob
            )
    }

