# Notebook cell 400: # @title  Establishment Safety and Idempotency
import hashlib

import json

import threading

import time

import uuid

from fastapi import Header, HTTPException

NARAD_API_IDEMPOTENCY_TTL_S = (
    NARAD_API_SESSION_TTL_S
)

NARAD_API_ESTABLISHMENT_EXECUTION_LOCK = (
    threading.Lock()
)

NARAD_API_IDEMPOTENCY_LOCK = (
    threading.RLock()
)

NARAD_API_IDEMPOTENCY_RECORDS = {}

def _narad_api_model_to_plain(
    value
):

    if hasattr(
        value,
        "model_dump"
    ):

        return value.model_dump()


    if hasattr(
        value,
        "dict"
    ):

        return value.dict()


    return value

def _narad_api_establishment_payload(
    request
):

    (
        sender,
        receiver
    ) = (

        _narad_api_canonical_endpoints(

            request.sender,

            request.receiver
        )
    )


    return {

        "sender":
            sender,

        "receiver":
            receiver,

        "qkd":
            _narad_api_model_to_plain(
                request.qkd
            ),

        "execution":
            _narad_api_model_to_plain(
                request.execution
            )
    }

def _narad_api_establishment_fingerprint(
    request
):

    payload = (

        _narad_api_establishment_payload(
            request
        )
    )


    encoded = (

        json.dumps(

            payload,

            sort_keys=True,

            separators=(
                ",",
                ":"
            ),

            default=str
        )
        .encode(
            "utf-8"
        )
    )


    return hashlib.sha256(
        encoded
    ).hexdigest()

def _narad_api_normalize_idempotency_key(
    value
):

    if value is None:

        return None


    value = (
        str(value)
        .strip()
    )


    if not value:

        raise HTTPException(

            status_code=400,

            detail=(
                "Idempotency-Key cannot be empty."
            )
        )


    if len(value) > 128:

        raise HTTPException(

            status_code=400,

            detail=(
                "Idempotency-Key exceeds 128 characters."
            )
        )


    return value

def _narad_api_prune_idempotency_records(
    *,
    now=None
):

    if now is None:

        now = time.time()


    removed = []


    with NARAD_API_IDEMPOTENCY_LOCK:

        for (
            key,
            record
        ) in list(

            NARAD_API_IDEMPOTENCY_RECORDS.items()
        ):

            # NEVER delete an in-flight record.
            if (
                record[
                    "status"
                ]
                ==
                "IN_PROGRESS"
            ):

                continue


            age_s = (

                float(now)

                -

                float(
                    record[
                        "updated_at_unix"
                    ]
                )
            )


            if (

                age_s

                >=

                NARAD_API_IDEMPOTENCY_TTL_S
            ):

                NARAD_API_IDEMPOTENCY_RECORDS.pop(

                    key,

                    None
                )


                removed.append(
                    key
                )


    return tuple(
        removed
    )

def _narad_api_public_idempotency_record(
    key,
    record
):

    output = {

        "idempotency_key":
            key,

        "status":
            record[
                "status"
            ],

        "created_at_unix":
            float(
                record[
                    "created_at_unix"
                ]
            ),

        "updated_at_unix":
            float(
                record[
                    "updated_at_unix"
                ]
            )
    }


    if (
        record[
            "status"
        ]
        ==
        "SUCCEEDED"
    ):

        response = (
            record[
                "response"
            ]
        )


        output[
            "session_id"
        ] = (

            response.get(
                "session_id"
            )
        )


    elif (
        record[
            "status"
        ]
        ==
        "FAILED"
    ):

        output[
            "error"
        ] = (
            record[
                "error"
            ]
        )


    return output

def _narad_api_execute_establishment_once(
    request
):

    (
        canonical_sender,
        canonical_receiver
    ) = (

        _narad_api_canonical_endpoints(

            request.sender,

            request.receiver
        )
    )


    qkd_config = (

        narad_api_make_qkd_config(
            request.qkd
        )
    )


    requested_cpu_workers = (
        request.execution.cpu_workers
    )


    requested_parallel_lanes = (
        request.execution.parallel_quantum_lanes
    )


    # ==================================================================
    # IMPORTANT:
    #
    # Current simulator does not contain a genuine global allocator for
    # competing simultaneous sessions.
    #
    # Until such an allocator exists, serialize PHYSICAL ESTABLISHMENT
    # rather than pretending independent simulator stacks compete for
    # the same resources.
    # ==================================================================

    with NARAD_API_ESTABLISHMENT_EXECUTION_LOCK:

        result = (

            narad_qc_establish_key(

                network=(
                    phase4_network
                ),

                sender_name=(
                    canonical_sender
                ),

                receiver_name=(
                    canonical_receiver
                ),

                qkd_config=(
                    qkd_config
                ),

                max_hops=(
                    request.execution.max_hops
                ),

                physical_seed=(
                    request.execution.physical_seed
                ),

                protocol_seed=(
                    request.execution.protocol_seed
                ),

                postprocess_seed=(
                    request.execution.postprocess_seed
                ),

                verbose=False,

                return_details=True
            )
        )


    _narad_api_prune_expired_sessions()


    session_id = (
        str(
            uuid.uuid4()
        )
    )


    now = time.time()


    with NARAD_API_SESSION_LOCK:

        NARAD_API_SESSIONS[
            session_id
        ] = {

            "session_id":
                session_id,

            "created_at_unix":
                now,

            "last_accessed_at_unix":
                now,

            "sender":
                result.sender,

            "receiver":
                result.receiver,

            # RAW KEY REMAINS SERVER-SIDE ONLY
            "key":
                bytes(
                    result.key
                ),

            "qkd_config":
                qkd_config,

            "result":
                result,

            "message_count":
                0
        }


    return {

        "session_id":
            session_id,

        "status":
            "ESTABLISHED",

        "sender":
            result.sender,

        "receiver":
            result.receiver,

        "session_ttl_s":
            NARAD_API_SESSION_TTL_S,

        "result":
            narad_api_public_result(
                result
            ),

        "execution": {

            "requested_cpu_workers":
                requested_cpu_workers,

            "applied_cpu_workers":
                1,

            "requested_parallel_quantum_lanes":
                requested_parallel_lanes,

            "applied_parallel_quantum_lanes":
                1,

            "establishment_concurrency":
                "SERIALIZED",

            "note": (
                "Current heterogeneous routed executor is "
                "single-lane and establishment runs are serialized "
                "until a network-wide concurrent resource allocator "
                "is implemented."
            )
        }
    }

def _narad_api_establish_idempotent(
    request,
    idempotency_key=None
):

    idempotency_key = (

        _narad_api_normalize_idempotency_key(
            idempotency_key
        )
    )


    # ==================================================================
    # No key supplied:
    #
    # Preserve backward compatibility.
    #
    # Request still benefits from global establishment serialization,
    # but automatic retry is NOT safe because there is no identity tying
    # two HTTP requests together.
    # ==================================================================

    if idempotency_key is None:

        response = (

            _narad_api_execute_establishment_once(
                request
            )
        )


        response[
            "idempotency"
        ] = {

            "protected":
                False,

            "key":
                None,

            "replayed":
                False,

            "note": (
                "No Idempotency-Key was supplied. "
                "Automatic retry after an uncertain timeout is unsafe."
            )
        }


        return response


    fingerprint = (

        _narad_api_establishment_fingerprint(
            request
        )
    )


    _narad_api_prune_idempotency_records()


    owner = False


    with NARAD_API_IDEMPOTENCY_LOCK:

        record = (

            NARAD_API_IDEMPOTENCY_RECORDS.get(
                idempotency_key
            )
        )


        if record is None:

            now = time.time()


            record = {

                "fingerprint":
                    fingerprint,

                "status":
                    "IN_PROGRESS",

                "created_at_unix":
                    now,

                "updated_at_unix":
                    now,

                "event":
                    threading.Event(),

                "response":
                    None,

                "error":
                    None
            }


            NARAD_API_IDEMPOTENCY_RECORDS[
                idempotency_key
            ] = record


            owner = True


        else:

            if (

                record[
                    "fingerprint"
                ]

                !=

                fingerprint
            ):

                raise HTTPException(

                    status_code=409,

                    detail=(
                        "Idempotency-Key was already used with "
                        "a different establishment request."
                    )
                )


    # ==================================================================
    # FIRST CALLER OWNS THE EXECUTION
    # ==================================================================

    if owner:

        try:

            response = (

                _narad_api_execute_establishment_once(
                    request
                )
            )


            response[
                "idempotency"
            ] = {

                "protected":
                    True,

                "key":
                    idempotency_key,

                "replayed":
                    False
            }


            with NARAD_API_IDEMPOTENCY_LOCK:

                record[
                    "status"
                ] = "SUCCEEDED"


                record[
                    "response"
                ] = response


                record[
                    "updated_at_unix"
                ] = time.time()


                record[
                    "event"
                ].set()


            return response


        except HTTPException as error:

            public_error = {

                "status_code":
                    int(
                        error.status_code
                    ),

                "detail":
                    error.detail
            }


            with NARAD_API_IDEMPOTENCY_LOCK:

                record[
                    "status"
                ] = "FAILED"


                record[
                    "error"
                ] = public_error


                record[
                    "updated_at_unix"
                ] = time.time()


                record[
                    "event"
                ].set()


            raise


        except Exception as error:

            public_error = {

                "status_code":
                    400,

                "detail": (
                    f"{type(error).__name__}: "
                    f"{error}"
                )
            }


            with NARAD_API_IDEMPOTENCY_LOCK:

                record[
                    "status"
                ] = "FAILED"


                record[
                    "error"
                ] = public_error


                record[
                    "updated_at_unix"
                ] = time.time()


                record[
                    "event"
                ].set()


            raise


    # ==================================================================
    # DUPLICATE CALL
    #
    # If original call is still running, wait for THAT call rather than
    # performing another physical/QKD execution.
    # ==================================================================

    event = (
        record[
            "event"
        ]
    )


    event.wait()


    with NARAD_API_IDEMPOTENCY_LOCK:

        status = (
            record[
                "status"
            ]
        )


        if status == "SUCCEEDED":

            # shallow/deep-safe JSON roundtrip copy;
            # public response contains no key bytes.
            replay_response = (

                json.loads(

                    json.dumps(
                        record[
                            "response"
                        ]
                    )
                )
            )


            replay_response[
                "idempotency"
            ][
                "replayed"
            ] = True


            return replay_response


        if status == "FAILED":

            error = (
                record[
                    "error"
                ]
            )


            raise HTTPException(

                status_code=int(
                    error[
                        "status_code"
                    ]
                ),

                detail=(
                    error[
                        "detail"
                    ]
                )
            )


    raise HTTPException(

        status_code=500,

        detail=(
            "Invalid NARAD-QC idempotency state."
        )
    )

_narad_api_remove_route(
    "/session/establish",
    "POST"
)

