# Notebook cell 402: # @title  HTTP Access Boundary Hardening
import hmac

import secrets

from starlette.middleware import Middleware

from starlette.middleware.base import BaseHTTPMiddleware

from starlette.responses import JSONResponse

if (
    "NARAD_API_ACCESS_KEY"
    not in globals()
):

    NARAD_API_ACCESS_KEY = (
        secrets.token_urlsafe(32)
    )

NARAD_API_ACCESS_HEADER = (
    "X-NARAD-API-Key"
)

NARAD_API_PUBLIC_EXACT_PATHS = frozenset(
    {
        "/",
        "/health",
        "/ready",
        "/docs",
        "/redoc",
        "/openapi.json",
        "/docs/oauth2-redirect",
    }
)

def _narad_api_path_is_public(
    path
):

    path = str(
        path
    )


    return bool(

        path
        in
        NARAD_API_PUBLIC_EXACT_PATHS
    )

def _narad_api_access_key_valid(
    candidate
):

    if candidate is None:

        return False


    candidate = str(
        candidate
    )


    if not candidate:

        return False


    return hmac.compare_digest(

        candidate,

        NARAD_API_ACCESS_KEY
    )

class NARADAPIAccessBoundaryMiddleware(
    BaseHTTPMiddleware
):

    async def dispatch(
        self,
        request,
        call_next
    ):

        path = (
            request.url.path
        )


        # --------------------------------------------------------------
        # Public operational/documentation endpoints.
        # --------------------------------------------------------------

        if _narad_api_path_is_public(
            path
        ):

            return await call_next(
                request
            )


        supplied_key = (

            request.headers.get(
                NARAD_API_ACCESS_HEADER
            )
        )


        if not _narad_api_access_key_valid(
            supplied_key
        ):

            return JSONResponse(

                status_code=401,

                content={

                    "detail":
                        "Valid NARAD-QC API access key required.",

                    "authentication_scheme":
                        "API_KEY",

                    "header":
                        NARAD_API_ACCESS_HEADER
                },

                headers={

                    "Cache-Control":
                        "no-store"
                }
            )


        response = await call_next(
            request
        )


        # --------------------------------------------------------------
        # Avoid caching authenticated research/session responses.
        # --------------------------------------------------------------

        response.headers[
            "Cache-Control"
        ] = "no-store"


        return response

app.user_middleware[:] = [

    middleware

    for middleware
    in app.user_middleware

    if (

        getattr(
            middleware,
            "cls",
            None
        )

        is not

        NARADAPIAccessBoundaryMiddleware
    )
]

app.user_middleware.insert(

    0,

    Middleware(
        NARADAPIAccessBoundaryMiddleware
    )
)

app.middleware_stack = (
    app.build_middleware_stack()
)

NARAD_API_ACCESS_BOUNDARY_VERSION = (
    "6.1E"
)

NARAD_API_AUTHENTICATION_MODEL = {

    "http_api_authentication":
        "API_KEY",

    "header":
        NARAD_API_ACCESS_HEADER,

    "node_authentication":
        "ML-DSA-65 simulated mutual authentication",

    "boundaries_are_distinct":
        True,

    "public_paths":
        sorted(
            NARAD_API_PUBLIC_EXACT_PATHS
        )
}


# Notebook cell 405: # @title  Runtime Parallelism + Live QKD Telemetry
from contextvars import ContextVar

from dataclasses import asdict, replace

import gc

import math

import multiprocessing as mp

import os

