if "NARAD_CONTROLLER_MAX_CPU_WORKERS" not in globals():

    NARAD_CONTROLLER_MAX_CPU_WORKERS = min(

        4,

        max(
            1,
            os.cpu_count()
            or
            1
        )
    )

_NARAD_EXECUTION_CONTEXT = ContextVar(

    "NARAD_EXECUTION_CONTEXT",

    default=None
)

_NARAD_PROGRESS_CALLBACK = ContextVar(

    "NARAD_PROGRESS_CALLBACK",

    default=None
)

if (
    "_NARAD_PRE_6_1F_BUILD_SELECTED_PATH_STACK"
    not in globals()
):

    _NARAD_PRE_6_1F_BUILD_SELECTED_PATH_STACK = (
        _narad_build_selected_path_stack
    )

if (
    "_NARAD_PRE_6_1F_ESTABLISH_KEY"
    not in globals()
):

    _NARAD_PRE_6_1F_ESTABLISH_KEY = (
        narad_qc_establish_key
    )

def _narad_runtime_cpu_count():

    return max(
        1,
        int(
            os.cpu_count()
            or
            1
        )
    )

def _narad_applied_cpu_workers(
    requested_workers,
    parallel_quantum_lanes
):

    requested_workers = max(
        1,
        int(
            requested_workers
        )
    )


    parallel_quantum_lanes = max(
        1,
        int(
            parallel_quantum_lanes
        )
    )


    runtime_limit = (
        _narad_runtime_cpu_count()
    )


    controller_limit = max(
        1,
        int(
            NARAD_CONTROLLER_MAX_CPU_WORKERS
        )
    )


    # ==============================================================
    # IMPORTANT:
    #
    # Independent CPU workers are useful only when there are
    # independent physical lane trajectories available to compute.
    #
    # One physical lane remains one causal execution stream.
    # ==============================================================

    return max(

        1,

        min(
            requested_workers,
            parallel_quantum_lanes,
            runtime_limit,
            controller_limit
        )
    )

def _narad_execution_state():

    state = (
        _NARAD_EXECUTION_CONTEXT.get()
    )


    if state is None:

        return {

            "requested_cpu_workers":
                1,

            "requested_parallel_quantum_lanes":
                1,

            "applied_cpu_workers":
                1,

            "applied_parallel_quantum_lanes":
                1,

            "worker_backend":
                "SEQUENTIAL"
        }


    return state

def _narad_safe_float(
    value
):

    if value is None:

        return None


    value = float(
        value
    )


    if not math.isfinite(
        value
    ):

        return None


    return value

def _narad_progress_payload(
    stage,
    qkd_config,
    summary=None,
    **extra
):

    payload = {

        "stage":
            str(
                stage
            ),

        "timestamp_unix":
            time.time(),

        "target_secret_bits":
            int(
                qkd_config.target_secret_bits
            ),

        "max_delivered_pairs":
            int(
                qkd_config.max_delivered_pairs
            )
    }


    if summary is not None:

        forecast = int(

            summary
            .forecast_extractable_bits
        )


        target = int(

            qkd_config
            .target_secret_bits
        )


        payload.update({

            "delivered_pairs":
                int(
                    summary.delivered_pairs
                ),

            "zz_bits":
                int(
                    summary.zz_key_basis_bits
                ),

            "xx_bits":
                int(
                    summary.xx_parameter_estimation_bits
                ),

            # Don't display "100% QBER" merely because no XX sample
            # exists yet.
            "observed_x_qber":
                (
                    _narad_safe_float(
                        summary.observed_x_qber
                    )

                    if (
                        summary
                        .xx_parameter_estimation_bits

                        >
                        0
                    )

                    else None
                ),

            "mean_predicted_qber":
                _narad_safe_float(
                    summary.mean_predicted_qber
                ),

            "phase_error_estimate":
                _narad_safe_float(
                    summary.phase_error_estimate
                ),

            "forecast_extractable_bits":
                forecast,

            "forecast_secret_fraction":
                float(

                    max(
                        0.0,

                        min(
                            1.0,

                            forecast
                            /
                            max(
                                1,
                                target
                            )
                        )
                    )
                ),

            "pair_budget_fraction":
                float(

                    max(
                        0.0,

                        min(
                            1.0,

                            summary.delivered_pairs
                            /
                            max(
                                1,
                                qkd_config
                                .max_delivered_pairs
                            )
                        )
                    )
                ),

            "collection_ready":
                bool(
                    summary.collection_ready
                ),

            "modeled_physical_time_s":
                _narad_safe_float(
                    summary.physical_time_s
                ),

            "elementary_generation_cycles":
                int(
                    summary
                    .elementary_generation_cycles
                ),

            "optical_mode_attempts":
                int(
                    summary
                    .optical_mode_attempts
                ),

            "bsm_attempts":
                int(
                    summary.bsm_attempts
                )
        })


    payload.update(
        extra
    )


    return payload

def _narad_emit_progress(
    stage,
    qkd_config,
    summary=None,
    **extra
):

    callback = (
        _NARAD_PROGRESS_CALLBACK.get()
    )


    if callback is None:

        return


    payload = (

        _narad_progress_payload(

            stage=(
                stage
            ),

            qkd_config=(
                qkd_config
            ),

            summary=(
                summary
            ),

            **extra
        )
    )


    # Telemetry must NEVER be able to kill the physics execution.
    try:

        callback(
            payload
        )

    except Exception as error:

        print(
            "[WARN] NARAD telemetry callback failed:",
            repr(
                error
            )
        )

def _narad_build_selected_path_stack(
    network,
    candidate_path,
    simulation_seed
):

    stack = (

        _NARAD_PRE_6_1F_BUILD_SELECTED_PATH_STACK(

            network=(
                network
            ),

            candidate_path=(
                candidate_path
            ),

            simulation_seed=(
                simulation_seed
            )
        )
    )


    stack[
        "_narad_network"
    ] = network


    stack[
        "_narad_candidate_path"
    ] = candidate_path


    stack[
        "_narad_route_physical_seed"
    ] = int(
        simulation_seed
    )


    return stack

_NARAD_ROUTED_FARM_CONTEXT = None

_NARAD_ROUTED_WORKER_THREAD_LIMITER = None

def _narad_routed_worker_initializer():

    global _NARAD_ROUTED_WORKER_THREAD_LIMITER


    try:

        from threadpoolctl import (
            threadpool_limits
        )


        _NARAD_ROUTED_WORKER_THREAD_LIMITER = (

            threadpool_limits(
                limits=1
            )
        )


    except Exception:

        _NARAD_ROUTED_WORKER_THREAD_LIMITER = None

def _narad_routed_worker_simulate_pair(
    pair_index
):

    global _NARAD_ROUTED_FARM_CONTEXT


    if _NARAD_ROUTED_FARM_CONTEXT is None:

        raise RuntimeError(
            "NARAD routed farm context is not initialized."
        )


    pair_index = int(
        pair_index
    )


    context = (
        _NARAD_ROUTED_FARM_CONTEXT
    )


    wall_start = (
        time.perf_counter()
    )


    cpu_start = (
        time.process_time()
    )


    qkd_config = (
        context[
            "qkd_config"
        ]
    )


    qkd_token = (

        _NARAD_REQUEST_QKD_CONFIG.set(
            qkd_config
        )
    )


    try:

        physical_seed = (

            _narad_derive_seed(

                master_seed=(
                    context[
                        "physical_seed"
                    ]
                ),

                path_index=(
                    pair_index
                ),

                stream_tag=(
                    61_001
                )
            )
        )


        protocol_seed = (

            _narad_derive_seed(

                master_seed=(
                    context[
                        "protocol_seed"
                    ]
                ),

                path_index=(
                    pair_index
                ),

                stream_tag=(
                    61_002
                )
            )
        )


        stack = (

            _narad_build_selected_path_stack(

                network=(
                    context[
                        "network"
                    ]
                ),

                candidate_path=(
                    context[
                        "candidate_path"
                    ]
                ),

                simulation_seed=(
                    physical_seed
                )
            )
        )


        # The outer route has already authenticated successfully.
        #
        # Each independently reconstructed physical-lane simulator
        # still needs its own local authorization gate opened before
        # quantum operations are legal.
        _narad_authenticate_selected_path(
            stack
        )


        channel = (

            NARADQKDEntanglementChannel(

                stack=(
                    stack
                ),

                protocol_seed=(
                    protocol_seed
                ),

                measurement_latency_s=0.0
            )
        )


        local_record = (

            channel
            .deliver_and_measure(

                alice_basis=None,

                bob_basis=None,

                z_probability=(
                    qkd_config
                    .z_probability
                ),

                max_slots_per_pair=(
                    qkd_config
                    .max_slots_per_pair
                )
            )
        )


        record = replace(

            local_record,

            pair_index=(
                pair_index
            )
        )


        payload = (
            asdict(
                record
            )
        )


        del channel
        del stack


        gc.collect()


        return {

            "pair_index":
                pair_index,

            "worker_pid":
                os.getpid(),

            "worker_cpu_s":
                float(
                    time.process_time()
                    -
                    cpu_start
                ),

            "worker_wall_s":
                float(
                    time.perf_counter()
                    -
                    wall_start
                ),

            "payload":
                payload
        }


    finally:

        _NARAD_REQUEST_QKD_CONFIG.reset(
            qkd_token
        )

class NARADRoutedTrajectoryFarm:

    def __init__(
        self,
        workers,
        lookahead
    ):

        self.requested_workers = max(
            1,
            int(
                workers
            )
        )


        self.applied_workers = (
            self.requested_workers
        )


        self.lookahead = max(
            1,
            int(
                lookahead
            )
        )


        self.pool = None

        self.pending = {}

        self.submitted_indices = set()

        self.worker_pids = set()

        self.submitted_count = 0

        self.retrieved_count = 0

        self.direct_fallback = False

        self.closed = False


        if self.requested_workers > 1:

            try:

                context = (
                    mp.get_context(
                        "fork"
                    )
                )


                self.pool = (

                    context.Pool(

                        processes=(
                            self.requested_workers
                        ),

                        initializer=(
                            _narad_routed_worker_initializer
                        )
                    )
                )


            except Exception as error:

                print(
                    "[WARN] Routed process farm unavailable:",
                    repr(
                        error
                    )
                )

                print(
                    "[INFO] Falling back to one CPU worker while "
                    "preserving requested physical-lane semantics."
                )


                self.pool = None

                self.direct_fallback = True

                self.applied_workers = 1


        else:

            self.direct_fallback = True

            self.applied_workers = 1


    def submit(
        self,
        pair_index
    ):

        pair_index = int(
            pair_index
        )


        if (
            pair_index
            in
            self.submitted_indices
        ):

            return


        self.submitted_indices.add(
            pair_index
        )


        self.submitted_count += 1


        if self.pool is not None:

            self.pending[
                pair_index
            ] = (

                self.pool
                .apply_async(

                    _narad_routed_worker_simulate_pair,

                    (
                        pair_index,
                    )
                )
            )


    def submit_through(
        self,
        final_pair_index
    ):

        final_pair_index = int(
            final_pair_index
        )


        if final_pair_index < 0:

            return


        start = (

            max(
                self.submitted_indices
            )
            +
            1

            if self.submitted_indices

            else 0
        )


        for pair_index in range(

            start,

            final_pair_index
            +
            1
        ):

            self.submit(
                pair_index
            )


    def maintain_window(
        self,
        next_pair_index,
        maximum_pair_index
    ):

        final_needed = min(

            int(
                maximum_pair_index
            ),

            int(
                next_pair_index
            )
            +
            self.lookahead
            -
            1
        )


        self.submit_through(
            final_needed
        )


    def _switch_to_direct_fallback(
        self,
        error
    ):

        print(
            "[WARN] Routed worker process failed:",
            repr(
                error
            )
        )


        print(
            "[INFO] Continuing with one CPU worker. "
            "Physical quantum-lane count is unchanged."
        )


        if self.pool is not None:

            try:

                self.pool.terminate()

                self.pool.join()

            except Exception:

                pass


        self.pool = None

        self.pending = {}

        self.direct_fallback = True

        self.applied_workers = 1


    def get(
        self,
        pair_index
    ):

        pair_index = int(
            pair_index
        )


        if (
            pair_index
            not in
            self.submitted_indices
        ):

            self.submit(
                pair_index
            )


        if self.pool is None:

            result = (

                _narad_routed_worker_simulate_pair(
                    pair_index
                )
            )


        else:

            try:

                result = (

                    self.pending[
                        pair_index
                    ]
                    .get()
                )


            except Exception as error:

                self._switch_to_direct_fallback(
                    error
                )


                result = (

                    _narad_routed_worker_simulate_pair(
                        pair_index
                    )
                )


        self.worker_pids.add(

            int(
                result[
                    "worker_pid"
                ]
            )
        )


        self.retrieved_count += 1


        self.pending.pop(
            pair_index,
            None
        )


        return (

            NARADQKDPairMeasurement(

                **result[
                    "payload"
                ]
            )
        )


    def snapshot(
        self
    ):

        pool_processes = 0


        if self.pool is not None:

            try:

                pool_processes = len(
                    self.pool._pool
                )

            except Exception:

                pool_processes = (
                    self.applied_workers
                )


        return {

            "requested_cpu_workers":
                self.requested_workers,

            "applied_cpu_workers":
                self.applied_workers,

            "worker_processes_created":
                pool_processes,

            "worker_processes_seen":
                len(
                    self.worker_pids
                ),

            "jobs_submitted":
                self.submitted_count,

            "trajectories_retrieved":
                self.retrieved_count,

            "jobs_pending":
                len(
                    self.pending
                ),

            "direct_fallback":
                bool(
                    self.direct_fallback
                )
        }


    def shutdown(
        self
    ):

        if self.closed:

            return


        if self.pool is not None:

            try:

                # Speculative trajectories are no longer relevant
                # once the requested key exists.
                self.pool.terminate()

                self.pool.join()

            except Exception:

                pass


        self.closed = True

_NARAD_RETRYABLE_POSTPROCESS_PREFIXES = (

    "INSUFFICIENT_PARAMETER_ESTIMATION",

    "CASCADE_RECONCILIATION_FAILED",

    "INSUFFICIENT_POST_EC_ENTROPY"
)

def _narad_try_actual_postprocessing(
    measurements,
    summary,
    qkd_config,
    postprocess_master_seed
):

    pair_number = int(
        summary.delivered_pairs
    )


    postprocess_rng = (

        np.random.default_rng(

            np.random.SeedSequence(
                [

                    int(
                        postprocess_master_seed
                    ),

                    pair_number,

                    int(
                        qkd_config
                        .target_secret_bits
                    )
                ]
            )
        )
    )


    try:

        result = (

            phase3k_distill_configurable_bbm92_key(

                measurements=(
                    tuple(
                        measurements
                    )
                ),

                collection_summary=(
                    summary
                ),

                config=(
                    qkd_config
                ),

                postprocess_rng=(
                    postprocess_rng
                )
            )
        )


    except RuntimeError as error:

        message = str(
            error
        )


        if not any(

            message.startswith(
                prefix
            )

            for prefix
            in
            _NARAD_RETRYABLE_POSTPROCESS_PREFIXES
        ):

            raise


        return (
            None,
            message
        )


    if (

        result.success

        and

        result.alice_key_bytes

        ==

        result.bob_key_bytes
    ):

        return (
            result,
            None
        )


    return (
        None,
        "POSTPROCESS_DID_NOT_PRODUCE_MATCHING_SECRET"
    )

def _narad_run_qkd_sequential_with_progress(
    stack,
    qkd_config,
    protocol_seed,
    postprocess_master_seed,
    verbose
):

    execution_state = (
        _narad_execution_state()
    )


    execution_state[
        "applied_cpu_workers"
    ] = 1


    execution_state[
        "applied_parallel_quantum_lanes"
    ] = 1


    execution_state[
        "worker_backend"
    ] = "SEQUENTIAL_CAUSAL_ROUTE"


    qkd_channel = (

        NARADQKDEntanglementChannel(

            stack=(
                stack
            ),

            protocol_seed=(
                int(
                    protocol_seed
                )
            ),

            measurement_latency_s=0.0
        )
    )


    measurements = []

    final_summary = None


    _narad_emit_progress(

        "QKD_COLLECTION",

        qkd_config,

        route=(
            stack[
                "_narad_candidate_path"
            ]
            .display_path
        ),

        applied_cpu_workers=1,

        applied_parallel_quantum_lanes=1
    )


    for pair_number in range(

        1,

        int(
            qkd_config.max_delivered_pairs
        )
        +
        1
    ):

        measurement = (

            qkd_channel
            .deliver_and_measure(

                alice_basis=None,

                bob_basis=None,

                z_probability=(
                    qkd_config.z_probability
                ),

                max_slots_per_pair=(
                    qkd_config
                    .max_slots_per_pair
                )
            )
        )


        measurements.append(
            measurement
        )


        if not _narad_should_check_qkd_block(

            pair_number=(
                pair_number
            ),

            config=(
                qkd_config
            )
        ):

            continue


        summary = (

            phase3j_bbm92_collection_summary(

                measurements=(
                    measurements
                ),

                config=(
                    qkd_config
                )
            )
        )


        final_summary = (
            summary
        )


        _narad_emit_progress(

            "QKD_COLLECTION",

            qkd_config,

            summary=(
                summary
            ),

            applied_cpu_workers=1,

            applied_parallel_quantum_lanes=1
        )


        if not summary.collection_ready:

            continue


        _narad_emit_progress(

            "QKD_POSTPROCESS",

            qkd_config,

            summary=(
                summary
            )
        )


        (
            final_result,
            retry_reason
        ) = (

            _narad_try_actual_postprocessing(

                measurements=(
                    measurements
                ),

                summary=(
                    summary
                ),

                qkd_config=(
                    qkd_config
                ),

                postprocess_master_seed=(
                    postprocess_master_seed
                )
            )
        )


        if final_result is not None:

            _narad_emit_progress(

                "COMPLETE",

                qkd_config,

                summary=(
                    summary
                ),

                final_secret_bits=int(
                    final_result.final_secret_bits
                )
            )


            return (
                final_result,
                tuple(
                    measurements
                ),
                summary
            )


        _narad_emit_progress(

            "QKD_COLLECTION",

            qkd_config,

            summary=(
                summary
            ),

            postprocess_retry_reason=(
                retry_reason
            )
        )


    if final_summary is None:

        final_summary = (

            phase3j_bbm92_collection_summary(

                measurements=(
                    measurements
                ),

                config=(
                    qkd_config
                )
            )
        )


    raise NARADQCServiceError(

        "QKD pair budget exhausted before actual "
        "post-processing produced the requested secret key. "
        f"Delivered={len(measurements)}, "
        f"forecast_extractable="
        f"{final_summary.forecast_extractable_bits}."
    )

def _narad_run_qkd_parallel_routed_lanes(
    stack,
    qkd_config,
    protocol_seed,
    postprocess_master_seed,
    verbose
):

    global _NARAD_ROUTED_FARM_CONTEXT


    execution_state = (
        _narad_execution_state()
    )


    requested_workers = int(

        execution_state[
            "requested_cpu_workers"
        ]
    )


    requested_lanes = int(

        execution_state[
            "requested_parallel_quantum_lanes"
        ]
    )


    applied_workers = (

        _narad_applied_cpu_workers(

            requested_workers,

            requested_lanes
        )
    )


    applied_lanes = max(
        1,
        requested_lanes
    )


    execution_state[
        "applied_cpu_workers"
    ] = applied_workers


    execution_state[
        "applied_parallel_quantum_lanes"
    ] = applied_lanes


    execution_state[
        "worker_backend"
    ] = "ROUTED_TRAJECTORY_FARM"


    candidate_path = (
        stack[
            "_narad_candidate_path"
        ]
    )


    _NARAD_ROUTED_FARM_CONTEXT = {

        "network":
            stack[
                "_narad_network"
            ],

        "candidate_path":
            candidate_path,

        "qkd_config":
            qkd_config,

        "physical_seed":
            int(
                stack[
                    "_narad_route_physical_seed"
                ]
            ),

        "protocol_seed":
            int(
                protocol_seed
            )
    }


    lookahead = max(

        applied_lanes,

        applied_workers
        *
        4
    )


    farm = (

        NARADRoutedTrajectoryFarm(

            workers=(
                applied_workers
            ),

            lookahead=(
                lookahead
            )
        )
    )


    # Pool creation may itself fall back to direct mode.
    execution_state[
        "applied_cpu_workers"
    ] = (
        farm.applied_workers
    )


    max_pairs = int(
        qkd_config.max_delivered_pairs
    )


    active_lanes = min(
        applied_lanes,
        max_pairs
    )


    active_heap = []

    measurements = []

    next_pair_index = 0

    final_summary = None

    last_physical_finish_s = 0.0


    try:

        initial_prefetch_end = min(

            max_pairs
            -
            1,

            active_lanes
            +
            lookahead
            -
            1
        )


        farm.submit_through(
            initial_prefetch_end
        )


        # ==========================================================
        # Populate each physical lane at modeled t = 0.
        # ==========================================================

        import heapq


        for lane_id in range(
            active_lanes
        ):

            record = (

                farm.get(
                    next_pair_index
                )
            )


            finish_s = float(
                record.delivery_physical_time_s
            )


            heapq.heappush(

                active_heap,

                (
                    finish_s,
                    lane_id,
                    next_pair_index,
                    record
                )
            )


            next_pair_index += 1


            farm.maintain_window(

                next_pair_index=(
                    next_pair_index
                ),

                maximum_pair_index=(
                    max_pairs
                    -
                    1
                )
            )


        _narad_emit_progress(

            "QKD_COLLECTION",

            qkd_config,

            route=(
                candidate_path
                .display_path
            ),

            applied_cpu_workers=(
                farm.applied_workers
            ),

            applied_parallel_quantum_lanes=(
                active_lanes
            ),

            worker_state=(
                farm.snapshot()
            )
        )


        # ==========================================================
        # Continuous completion-event execution.
        # ==========================================================

        while active_heap:

            (
                physical_finish_s,
                lane_id,
                trajectory_index,
                record
            ) = (

                heapq.heappop(
                    active_heap
                )
            )


            last_physical_finish_s = float(
                physical_finish_s
            )


            completion_index = len(
                measurements
            )


            completed_record = replace(

                record,

                pair_index=(
                    completion_index
                )
            )


            measurements.append(
                completed_record
            )


            delivered = len(
                measurements
            )


            should_check = (

                _narad_should_check_qkd_block(

                    pair_number=(
                        delivered
                    ),

                    config=(
                        qkd_config
                    )
                )
            )


            if should_check:

                raw_summary = (

                    phase3j_bbm92_collection_summary(

                        measurements=(
                            measurements
                        ),

                        config=(
                            qkd_config
                        )
                    )
                )


                summary = replace(

                    raw_summary,

                    physical_time_s=(
                        float(
                            physical_finish_s
                        )
                    )
                )


                final_summary = (
                    summary
                )


                execution_state[
                    "applied_cpu_workers"
                ] = (
                    farm.applied_workers
                )


                _narad_emit_progress(

                    "QKD_COLLECTION",

                    qkd_config,

                    summary=(
                        summary
                    ),

                    applied_cpu_workers=(
                        farm.applied_workers
                    ),

                    applied_parallel_quantum_lanes=(
                        active_lanes
                    ),

                    worker_state=(
                        farm.snapshot()
                    )
                )


                if summary.collection_ready:

                    _narad_emit_progress(

                        "QKD_POSTPROCESS",

                        qkd_config,

                        summary=(
                            summary
                        ),

                        worker_state=(
                            farm.snapshot()
                        )
                    )


                    (
                        final_result,
                        retry_reason
                    ) = (

                        _narad_try_actual_postprocessing(

                            measurements=(
                                measurements
                            ),

                            summary=(
                                summary
                            ),

                            qkd_config=(
                                qkd_config
                            ),

                            postprocess_master_seed=(
                                postprocess_master_seed
                            )
                        )
                    )


                    if final_result is not None:

                        _narad_emit_progress(

                            "COMPLETE",

                            qkd_config,

                            summary=(
                                summary
                            ),

                            final_secret_bits=int(
                                final_result
                                .final_secret_bits
                            ),

                            worker_state=(
                                farm.snapshot()
                            )
                        )


                        return (

                            final_result,

                            tuple(
                                measurements
                            ),

                            summary
                        )


                    _narad_emit_progress(

                        "QKD_COLLECTION",

                        qkd_config,

                        summary=(
                            summary
                        ),

                        postprocess_retry_reason=(
                            retry_reason
                        )
                    )


            # ======================================================
            # Refill the physical lane which just became free.
            # ======================================================

            if next_pair_index < max_pairs:

                next_record = (

                    farm.get(
                        next_pair_index
                    )
                )


                next_finish_s = (

                    float(
                        physical_finish_s
                    )

                    +

                    float(
                        next_record
                        .delivery_physical_time_s
                    )
                )


                heapq.heappush(

                    active_heap,

                    (
                        next_finish_s,
                        lane_id,
                        next_pair_index,
                        next_record
                    )
                )


                next_pair_index += 1


                farm.maintain_window(

                    next_pair_index=(
                        next_pair_index
                    ),

                    maximum_pair_index=(
                        max_pairs
                        -
                        1
                    )
                )


        if final_summary is None:

            raw_summary = (

                phase3j_bbm92_collection_summary(

                    measurements=(
                        measurements
                    ),

                    config=(
                        qkd_config
                    )
                )
            )


            final_summary = replace(

                raw_summary,

                physical_time_s=(
                    float(
                        last_physical_finish_s
                    )
                )
            )


        raise NARADQCServiceError(

            "QKD pair budget exhausted before actual "
            "post-processing produced the requested secret key. "
            f"Delivered={len(measurements)}, "
            f"forecast_extractable="
            f"{final_summary.forecast_extractable_bits}."
        )


    finally:

        execution_state[
            "applied_cpu_workers"
        ] = (
            farm.applied_workers
        )


        execution_state[
            "worker_snapshot"
        ] = (
            farm.snapshot()
        )


        farm.shutdown()


        _NARAD_ROUTED_FARM_CONTEXT = None

def _narad_run_qkd_until_actual_key(
    stack,
    qkd_config,
    protocol_seed,
    postprocess_master_seed,
    verbose
):

    execution_state = (
        _narad_execution_state()
    )


    requested_lanes = int(

        execution_state[
            "requested_parallel_quantum_lanes"
        ]
    )


    if requested_lanes <= 1:

        return (

            _narad_run_qkd_sequential_with_progress(

                stack=(
                    stack
                ),

                qkd_config=(
                    qkd_config
                ),

                protocol_seed=(
                    protocol_seed
                ),

                postprocess_master_seed=(
                    postprocess_master_seed
                ),

                verbose=(
                    verbose
                )
            )
        )


    return (

        _narad_run_qkd_parallel_routed_lanes(

            stack=(
                stack
            ),

            qkd_config=(
                qkd_config
            ),

            protocol_seed=(
                protocol_seed
            ),

            postprocess_master_seed=(
                postprocess_master_seed
            ),

            verbose=(
                verbose
            )
        )
    )

def narad_qc_establish_key(
    network,
    sender_name,
    receiver_name,
    *,
    qkd_config=PHASE3J_BIASED_BBM92_CONFIG,
    max_hops=None,
    physical_seed=NARAD_API_DEFAULT_PHYSICAL_SEED,
    protocol_seed=NARAD_API_DEFAULT_PROTOCOL_SEED,
    postprocess_seed=NARAD_API_DEFAULT_POSTPROCESS_SEED,
    verbose=True,
    return_details=False,
    cpu_workers=1,
    parallel_quantum_lanes=1,
    progress_callback=None,
    execution_audit=None
):

    requested_workers = max(
        1,
        int(
            cpu_workers
        )
    )


    requested_lanes = max(
        1,
        int(
            parallel_quantum_lanes
        )
    )


    if execution_audit is None:

        execution_audit = {}


    execution_audit.update({

        "requested_cpu_workers":
            requested_workers,

        "requested_parallel_quantum_lanes":
            requested_lanes,

        "applied_cpu_workers":
            _narad_applied_cpu_workers(
                requested_workers,
                requested_lanes
            ),

        "applied_parallel_quantum_lanes":
            requested_lanes,

        "worker_backend":
            (
                "ROUTED_TRAJECTORY_FARM"

                if requested_lanes > 1

                else "SEQUENTIAL_CAUSAL_ROUTE"
            )
    })


    execution_token = (

        _NARAD_EXECUTION_CONTEXT.set(
            execution_audit
        )
    )


    progress_token = (

        _NARAD_PROGRESS_CALLBACK.set(
            progress_callback
        )
    )


    try:

        return (

            _NARAD_PRE_6_1F_ESTABLISH_KEY(

                network=(
                    network
                ),

                sender_name=(
                    sender_name
                ),

                receiver_name=(
                    receiver_name
                ),

                qkd_config=(
                    qkd_config
                ),

                max_hops=(
                    max_hops
                ),

                physical_seed=(
                    physical_seed
                ),

                protocol_seed=(
                    protocol_seed
                ),

                postprocess_seed=(
                    postprocess_seed
                ),

                verbose=(
                    verbose
                ),

                return_details=(
                    return_details
                )
            )
        )


    finally:

        _NARAD_PROGRESS_CALLBACK.reset(
            progress_token
        )


        _NARAD_EXECUTION_CONTEXT.reset(
            execution_token
        )


# Notebook cell 406: # @title API Worker + Progress Wiring
from contextvars import ContextVar

import time

_NARAD_ACTIVE_IDEMPOTENCY_KEY = ContextVar(

    "NARAD_ACTIVE_IDEMPOTENCY_KEY",

    default=None
)

if (
    "_NARAD_PRE_6_1F_ESTABLISH_IDEMPOTENT"
    not in globals()
):

    _NARAD_PRE_6_1F_ESTABLISH_IDEMPOTENT = (
        _narad_api_establish_idempotent
    )

if (
    "_NARAD_PRE_6_1F_PUBLIC_IDEMPOTENCY_RECORD"
    not in globals()
):

    _NARAD_PRE_6_1F_PUBLIC_IDEMPOTENCY_RECORD = (
        _narad_api_public_idempotency_record
    )

def _narad_api_establish_idempotent(
    request,
    idempotency_key=None
):

    normalized_key = (

        _narad_api_normalize_idempotency_key(
            idempotency_key
        )
    )


    token = (

        _NARAD_ACTIVE_IDEMPOTENCY_KEY.set(
            normalized_key
        )
    )


    try:

        return (

            _NARAD_PRE_6_1F_ESTABLISH_IDEMPOTENT(

                request,

                idempotency_key=(
                    normalized_key
                )
            )
        )


    finally:

        _NARAD_ACTIVE_IDEMPOTENCY_KEY.reset(
            token
        )

def _narad_api_progress_callback_for_current_request():

    idempotency_key = (

        _NARAD_ACTIVE_IDEMPOTENCY_KEY.get()
    )


    if idempotency_key is None:

        return None


    def publish(
        payload
    ):

        with NARAD_API_IDEMPOTENCY_LOCK:

            record = (

                NARAD_API_IDEMPOTENCY_RECORDS.get(
                    idempotency_key
                )
            )


            if record is None:

                return


            record[
                "progress"
            ] = dict(
                payload
            )


            record[
                "updated_at_unix"
            ] = time.time()


    return publish

def _narad_api_public_idempotency_record(
    key,
    record
):

    output = (

        _NARAD_PRE_6_1F_PUBLIC_IDEMPOTENCY_RECORD(

            key,

            record
        )
    )


    progress = (

        record.get(
            "progress"
        )
    )


    if progress is not None:

        output[
            "progress"
        ] = dict(
            progress
        )


    else:

        output[
            "progress"
        ] = None


    return output

def _narad_api_execute_establishment_once(
    request
):

    (
        canonical_sender,
        canonical_receiver
    ) = (

        _narad_api_canonical_endpoints(

            request.sender,

            request.receiver
        )
    )


    qkd_config = (

        narad_api_make_qkd_config(
            request.qkd
        )
    )


    requested_cpu_workers = int(
        request.execution.cpu_workers
    )


    requested_parallel_lanes = int(
        request.execution.parallel_quantum_lanes
    )


    execution_audit = {}


    progress_callback = (

        _narad_api_progress_callback_for_current_request()
    )


    if progress_callback is not None:

        progress_callback({

            "stage":
                "ROUTE_SELECTION_AND_AUTHENTICATION",

            "timestamp_unix":
                time.time(),

            "requested_cpu_workers":
                requested_cpu_workers,

            "requested_parallel_quantum_lanes":
                requested_parallel_lanes,

            "target_secret_bits":
                int(
                    qkd_config.target_secret_bits
                )
        })


    # ==================================================================
    # 6.1D global establishment serialization remains intact.
    #
    # One NARAD network establishment at a time;
    # internal CPU workers may parallelize that one request.
    # ==================================================================

    with NARAD_API_ESTABLISHMENT_EXECUTION_LOCK:

        result = (

            narad_qc_establish_key(

                network=(
                    phase4_network
                ),

                sender_name=(
                    canonical_sender
                ),

                receiver_name=(
                    canonical_receiver
                ),

                qkd_config=(
                    qkd_config
                ),

                max_hops=(
                    request.execution.max_hops
                ),

                physical_seed=(
                    request.execution.physical_seed
                ),

                protocol_seed=(
                    request.execution.protocol_seed
                ),

                postprocess_seed=(
                    request.execution.postprocess_seed
                ),

                verbose=False,

                return_details=True,

                cpu_workers=(
                    requested_cpu_workers
                ),

                parallel_quantum_lanes=(
                    requested_parallel_lanes
                ),

                progress_callback=(
                    progress_callback
                ),

                execution_audit=(
                    execution_audit
                )
            )
        )


    _narad_api_prune_expired_sessions()


    session_id = (
        str(
            uuid.uuid4()
        )
    )


    now = time.time()


    with NARAD_API_SESSION_LOCK:

        NARAD_API_SESSIONS[
            session_id
        ] = {

            "session_id":
                session_id,

            "created_at_unix":
                now,

            "last_accessed_at_unix":
                now,

            "sender":
                result.sender,

            "receiver":
                result.receiver,

            "key":
                bytes(
                    result.key
                ),

            "qkd_config":
                qkd_config,

            "result":
                result,

            "execution":
                dict(
                    execution_audit
                ),

            "message_count":
                0
        }


    if progress_callback is not None:

        progress_callback({

            "stage":
                "SESSION_ESTABLISHED",

            "timestamp_unix":
                time.time(),

            "target_secret_bits":
                int(
                    qkd_config.target_secret_bits
                ),

            "final_secret_bits":
                int(
                    result.final_secret_bits
                ),

            "delivered_pairs":
                int(
                    result.delivered_pairs
                ),

            "zz_bits":
                int(
                    result.zz_raw_key_bits
                ),

            "xx_bits":
                int(
                    result.xx_parameter_estimation_bits
                ),

            "forecast_secret_fraction":
                1.0,

            "pair_budget_fraction":
                float(

                    result.delivered_pairs
                    /
                    max(
                        1,
                        qkd_config.max_delivered_pairs
                    )
                ),

            "applied_cpu_workers":
                int(
                    execution_audit[
                        "applied_cpu_workers"
                    ]
                ),

            "applied_parallel_quantum_lanes":
                int(
                    execution_audit[
                        "applied_parallel_quantum_lanes"
                    ]
                )
        })


    return {

        "session_id":
            session_id,

        "status":
            "ESTABLISHED",

        "sender":
            result.sender,

        "receiver":
            result.receiver,

        "session_ttl_s":
            NARAD_API_SESSION_TTL_S,

        "result":
            narad_api_public_result(
                result
            ),

        "execution": {

            **execution_audit,

            "runtime_logical_cpus":
                _narad_runtime_cpu_count(),

            "controller_worker_limit":
                int(
                    NARAD_CONTROLLER_MAX_CPU_WORKERS
                ),

            "establishment_concurrency":
                "SERIALIZED_BETWEEN_SESSIONS",

            "note": (
                "CPU workers parallelize independent routed "
                "quantum-lane trajectories. CPU worker count and "
                "physical quantum-lane count are distinct controls."
            )
        }
    }

